const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['협업 플랫폼 개선','검증 자동화','데이터 분석 도구','통합 모니터링','문서 관리 고도화','배포 체계 개선','운영 지원','사용자 포털','API 품질 개선','공통 모듈 정리','실험 환경 구축','검색 성능 개선','알림 서비스','접근 권한 개선','로그 분석'];
const titles=[['공용 일정 편집 기능 검증','과제 필터 사용성 개선'],['회귀 시험 시나리오 보완','실패 케이스 결과 정리'],['분석 화면 지표 검토','입력 데이터 정합성 확인'],['상태 표시 개선','모니터링 알림 검토'],['작성 문서 검토','사용 가이드 보완'],['배포 절차 점검','업데이트 테스트'],['문의 사항 확인','운영 이슈 대응'],['포털 화면 검토','참여 과제 연결 점검']];
const colors=['#5369d8','#4c9a83','#b8894e','#8b6daf','#6396b3','#af7089','#7d8d55','#78869e'];
let mode=new URLSearchParams(location.search).get('case')||'B',count=8,active=0,opened=0,kind='daily',date='2026-10-27',scenario='new',projects=[],sources=[],reports={},selected=new Set(),filter='',search='',toastTimer;
const descriptions={A:['필요한 캘린더 항목을 골라 보고서에 붙이기','왼쪽에서 복수 선택 또는 드래그, 오른쪽에서 보고 문구 편집. 필요한 내용만 보고할 때 적합합니다.'],B:['한 과제에 집중하고, 옆에서 캘린더 항목 가져오기','과제 목록은 고정하고 입력 공간을 재사용합니다. 여러 과제를 오가며 긴 내용을 작성하는 방향입니다.'],C:['캘린더로 채운 초안을 한눈에 검토하기','과제와 시간은 표에서 확인하고 필요한 행만 펼칩니다. 대부분의 캘린더 내용을 보고하는 날에 적합합니다.']};
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('on'),2300);}
function init(){if(!descriptions[mode])mode='B';projects=names.slice(0,count).map((name,i)=>({id:'p'+i,name,color:colors[i%colors.length],hours:Number(((kind==='weekly'?40:8)/count).toFixed(2))}));sources=projects.flatMap((p,i)=>titles[i%titles.length].map((title,j)=>({id:p.id+'s'+j,pid:p.id,title,time:j?'오후, 할 일':'오전, 일정',text:j?'사용자 관점에서 개선 사항을 정리하고 다음 검토에 반영':'정상 동작과 예외 상황을 확인\n변경 사항 및 시험 결과를 정리',date,tag:j?'할 일':'일정'})));if(kind==='weekly'){const daily=sources;sources=Array.from({length:5},(_,day)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+day);const ds=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return daily.map(x=>({...x,id:x.id+'d'+day,date:ds}));}).flat();}reports={};projects.forEach(p=>reports[p.id]={hours:p.hours,blocks:[],plan:'',included:true});active=0;opened=mode==='C'?-1:0;selected.clear();filter='';search='';if(mode==='C')sources.forEach(s=>insert(s.id,false));if(scenario==='saved'){Object.values(reports).forEach(r=>r.blocks=[]);reports.p0.blocks=[{id:'saved-1',sourceId:null,text:'기존에 보고한 내용을 검토하고 후속 작업을 진행했습니다.',enabled:true,origin:'기존 보고'}];}render();}
function includedBlocks(pid){return reports[pid].blocks.filter(b=>b.enabled);}
function sourceUsed(id){return Object.values(reports).some(r=>r.blocks.some(b=>b.sourceId===id));}
function insert(id,announce=true){const s=sources.find(x=>x.id===id);if(!s||sourceUsed(id))return false;reports[s.pid].blocks.push({id:'b'+id,sourceId:id,text:s.title+'\n'+s.text,enabled:true,origin:s.tag});if(announce)notify('보고서에 추가했습니다. 캘린더 원본은 바뀌지 않습니다.');return true;}
function hour(pid,value){reports[pid].hours=value===''?'':Number(value);updateFoot();}
function setCase(k){mode=k;history.replaceState(null,'','?case='+k);init();}
function setDate(d){date=d;$('#reportDate').value=d;init();$('#veil').classList.remove('hidden');notify('선택한 날짜의 예시 캘린더를 열었습니다.');}
function render(){if(!descriptions[mode])mode='B';$$('.variants button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===mode)));$('#caseTitle').textContent=descriptions[mode][0];$('#caseDesc').textContent=descriptions[mode][1];$('#editTitle').textContent=(kind==='weekly'?'주간보고':'일간보고')+(scenario==='saved'?' 편집':' 작성');$('#reportOrigin').textContent=scenario==='saved'?'기존 보고를 유지하며 필요한 항목 추가':'캘린더에서 보고로';$('#periodLabel').textContent=date+(kind==='weekly'?'부터 5일간의 캘린더 기준':' 캘린더 기준');$('#attendanceStatus').closest('label').hidden=kind==='weekly';const w=$('#workspace');w.dataset.case=mode;w.innerHTML='';if(mode==='A')renderA(w);if(mode==='B')renderB(w);if(mode==='C')renderC(w);renderDays();updateFoot();positionVeil();}
function positionVeil(){$('#veil').style.top=$('.lab').getBoundingClientRect().bottom+'px';}
function renderDays(){const base=new Date(date+'T12:00:00');$('#days').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(d.getDate()+i-2);const ds=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return '<button data-day="'+ds+'" class="'+(ds===date?'today':'')+'"><span>'+d.getDate()+' '+['일','월','화','수','목','금','토'][d.getDay()]+'</span>'+(i===2||i===1?'<span class="date-report">'+(i===1?'저장된 보고':'캘린더 업무 '+sources.length+'건')+'</span>':'')+'</button>';}).join('');$$('[data-day]').forEach(b=>b.onclick=()=>setDate(b.dataset.day));}
function sourceCard(s){const used=sourceUsed(s.id);return '<article class="source-card '+(used?'added':'')+'" draggable="'+!used+'" data-source="'+s.id+'"><div class="source-time">'+(kind==='weekly'?s.date+', ':'')+s.time+'</div><div class="source-name">'+esc(s.title)+'</div><p class="source-text">'+esc(s.text)+'</p><div class="source-actions">'+(used?'<span class="added-label">✓ 보고서에 추가됨</span>':'<label><input type="checkbox" data-pick="'+s.id+'" '+(selected.has(s.id)?'checked':'')+'>선택</label>')+'<button data-add="'+s.id+'" '+(used?'disabled':'')+'>'+(used?'추가됨':'+ 보고에 추가')+'</button></div></article>';}
function library(activeOnly=false){const pane=document.createElement('aside');pane.className='pane library'+(activeOnly?' right':'');pane.setAttribute('aria-label','캘린더 원본');pane.innerHTML='<div class="pane-head"><h3>캘린더에서 가져오기</h3><span>'+sources.filter(s=>!activeOnly||s.pid===projects[active].id).length+'개 항목</span></div><p class="intro">'+(activeOnly?'이 과제의 캘린더 내용입니다. 필요한 항목만 보고에 추가하세요.':'일정 제목과 메모를 보고용 블록으로 가져옵니다. 필요한 항목을 고르세요.')+'</p>'+(!activeOnly?'<div class="source-tools"><select id="sourceProject" aria-label="원본 과제 필터"><option value="">모든 과제</option>'+projects.map(p=>'<option value="'+p.id+'" '+(filter===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></div>':'')+'<div class="source-tools"><input type="search" id="sourceSearch" placeholder="캘린더 항목 찾기" value="'+esc(search)+'" aria-label="캘린더 항목 찾기"></div><div id="sourceItems"></div><div class="bulkbar"><small id="selectionCount">'+selected.size+'개 선택</small><button class="small" id="addSelected">선택 항목 추가</button></div>';
 const items=pane.querySelector('#sourceItems');let shown=sources.filter(s=>(!activeOnly||s.pid===projects[active].id)&&(!filter||activeOnly||s.pid===filter)&&(!search||(s.title+s.text).includes(search)));let previous='';items.innerHTML=shown.map(s=>{let h='';if(s.pid!==previous){const p=projects.find(p=>p.id===s.pid);h='<div class="source-group"><span class="dot" style="--pc:'+p.color+'"></span>'+esc(p.name)+'</div>';previous=s.pid;}return h+sourceCard(s);}).join('')||'<p class="source-filter-result">일치하는 캘린더 항목이 없습니다.</p>';
 if(!activeOnly)pane.querySelector('#sourceProject').onchange=e=>{filter=e.target.value;render();};pane.querySelector('#sourceSearch').oninput=e=>{const focus=e.target.selectionStart;search=e.target.value;render();const x=$('#sourceSearch');x.focus();if(x.type==='text')x.setSelectionRange(focus,focus);};pane.querySelector('#addSelected').onclick=()=>{let n=0;[...selected].forEach(id=>{if(insert(id,false))n++;});selected.clear();render();notify(n+'개 항목을 과제별로 추가했습니다.');};return pane;
}
function wireSources(root){root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{insert(b.dataset.add);render();});root.querySelectorAll('[data-pick]').forEach(c=>c.onchange=()=>{if(c.checked)selected.add(c.dataset.pick);else selected.delete(c.dataset.pick);$('#selectionCount').textContent=selected.size+'개 선택';});root.querySelectorAll('[data-source]').forEach(card=>card.ondragstart=e=>{e.dataTransfer.setData('text/plain',card.dataset.source);e.dataTransfer.effectAllowed='copy';});}
function bindDrop(el,pid){el.classList.add('drop-target');el.ondragover=e=>{e.preventDefault();el.classList.add('drag-over');};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=e=>{e.preventDefault();el.classList.remove('drag-over');const s=sources.find(s=>s.id===e.dataTransfer.getData('text/plain'));if(!s)return;if(pid&&s.pid!==pid){notify('해당 과제의 캘린더 항목을 추가하세요.');return;}insert(s.id);render();};}
function blockHTML(b,pid,review=false){return '<div class="report-block '+(!b.enabled?'excluded':'')+'" data-block="'+b.id+'"><div class="block-head"><div class="origin">'+(review?'<input type="checkbox" data-enable="'+b.id+'" aria-label="보고에 포함" '+(b.enabled?'checked':'')+'>':'')+'<span class="tag">'+esc(b.origin)+'</span><span>'+(b.sourceId?'캘린더에서 가져옴':'보고에서 작성')+'</span></div><div class="block-actions"><button data-up="'+b.id+'" title="위로 이동" aria-label="블록 위로 이동">↑</button><button data-delete="'+b.id+'" title="보고에서 제외" aria-label="블록 보고에서 제외">×</button></div></div><textarea data-edit="'+b.id+'" aria-label="보고용 업무 내용">'+esc(b.text)+'</textarea></div>';}
function findBlock(id){for(const p of projects){const b=reports[p.id].blocks.find(x=>x.id===id);if(b)return {b,pid:p.id};}return null;}
function wireReport(root){root.querySelectorAll('[data-edit]').forEach(t=>t.oninput=()=>{findBlock(t.dataset.edit).b.text=t.value;updateFoot();});root.querySelectorAll('[data-hours]').forEach(i=>i.oninput=()=>hour(i.dataset.hours,i.value));root.querySelectorAll('[data-plan]').forEach(t=>t.oninput=()=>reports[t.dataset.plan].plan=t.value);root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const x=findBlock(b.dataset.delete);reports[x.pid].blocks=reports[x.pid].blocks.filter(y=>y.id!==x.b.id);render();notify('보고에서 제외했습니다. 캘린더 원본은 그대로입니다.');});root.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{const x=findBlock(b.dataset.up),arr=reports[x.pid].blocks,i=arr.indexOf(x.b);if(i>0)[arr[i-1],arr[i]]=[arr[i],arr[i-1]];render();});root.querySelectorAll('[data-enable]').forEach(c=>c.onchange=()=>{findBlock(c.dataset.enable).b.enabled=c.checked;render();});root.querySelectorAll('[data-free]').forEach(b=>b.onclick=()=>{const pid=b.dataset.free,id='free'+Date.now();reports[pid].blocks.push({id,sourceId:null,text:'',enabled:true,origin:'직접 입력'});render();$('[data-edit="'+id+'"]').focus();});}
function groupHeader(p){return '<div class="group-head"><div class="group-name"><span class="dot" style="--pc:'+p.color+'"></span>'+esc(p.name)+'</div><label class="hours-label">투입 시간 <input type="number" min="0" step="0.25" value="'+reports[p.id].hours+'" data-hours="'+p.id+'" aria-label="'+esc(p.name)+' 투입 시간">시간</label></div>';}
function planHTML(p){return kind==='weekly'?'<div class="week-plan"><label>차주 계획</label><textarea data-plan="'+p.id+'" aria-label="'+esc(p.name)+' 차주 계획" placeholder="다음 주 진행할 업무">'+esc(reports[p.id].plan)+'</textarea></div>':'';}
function renderA(w){w.appendChild(library());const doc=document.createElement('main');doc.className='pane document';const ps=projects.filter(p=>reports[p.id].blocks.length);doc.innerHTML='<div class="document-title"><div><h2>보고서에 담을 내용</h2><p>블록을 추가한 뒤 보고 문구를 직접 다듬으세요.</p></div><select id="manualProject" aria-label="직접 작성할 과제"><option value="">+ 과제 직접 작성</option>'+projects.map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join('')+'</select></div>'+(!ps.length?'<div class="empty"><strong>캘린더 항목을 골라 담아보세요</strong><p>왼쪽에서 항목을 추가하거나 이곳으로 끌어오세요.<br>과제별로 자동 정리되고, 같은 항목은 중복 추가하지 않습니다.</p></div>':'')+ps.map(p=>'<section class="report-group">'+groupHeader(p)+reports[p.id].blocks.map(b=>blockHTML(b,p.id)).join('')+'<button class="add-text" data-free="'+p.id+'">+ 캘린더에 없는 내용 직접 쓰기</button>'+planHTML(p)+'</section>').join('');w.appendChild(doc);$('#manualProject').onchange=e=>{if(!e.target.value)return;const id='free'+Date.now();reports[e.target.value].blocks.push({id,sourceId:null,text:'',enabled:true,origin:'직접 입력'});render();$('[data-edit="'+id+'"]').focus();};bindDrop(doc);wireSources(w);wireReport(w);}
function renderB(w){const nav=document.createElement('nav');nav.className='project-nav';nav.setAttribute('aria-label','보고 과제');nav.innerHTML='<header>보고 과제 '+projects.length+'개</header>'+projects.map((p,i)=>'<button data-project="'+i+'" class="'+(i===active?'active':'')+'" aria-current="'+(i===active?'true':'false')+'"><span class="dot" style="--pc:'+p.color+'"></span><span><strong>'+esc(p.name)+'</strong><small>'+reports[p.id].hours+'시간, '+includedBlocks(p.id).length+'개 블록</small></span><span class="status-dot">'+(includedBlocks(p.id).length?'✓':'')+'</span></button>').join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>{active=Number(b.dataset.project);selected.clear();search='';render();});w.appendChild(nav);const p=projects[active],doc=document.createElement('main');doc.className='pane focus-editor';doc.innerHTML=groupHeader(p)+'<div class="subhead"><span>보고에 포함할 업무</span><span>캘린더 시간 '+p.hours+'시간</span></div>'+(!reports[p.id].blocks.length?'<div class="empty"><strong>이 과제의 업무를 추가하세요</strong><p>오른쪽 캘린더 항목을 선택해 추가하거나<br>아래에서 직접 입력할 수 있습니다.</p></div>':'')+reports[p.id].blocks.map(b=>blockHTML(b,p.id)).join('')+'<button class="add-text" data-free="'+p.id+'">+ 캘린더에 없는 내용 직접 쓰기</button>'+planHTML(p)+(active<projects.length-1?'<button class="next-task" id="nextProject">다음 과제: '+esc(projects[active+1].name)+' →</button>':'');w.appendChild(doc);w.appendChild(library(true));if($('#nextProject'))$('#nextProject').onclick=()=>{active++;selected.clear();search='';render();};bindDrop(doc,p.id);wireSources(w);wireReport(w);}
function renderC(w){const sheet=document.createElement('main');sheet.className='pane sheet';sheet.innerHTML='<div class="sheet-intro"><div><h2>'+(scenario==='saved'?'저장된 보고를 검토하세요':'캘린더로 만든 초안을 검토하세요')+'</h2><p>'+(scenario==='saved'?'기존 문구를 유지합니다. 캘린더로 다시 채우려면 명시적으로 선택합니다.':'업무와 시간은 이미 채워두었습니다. 과제 또는 블록을 제외하고 필요한 문구를 고치세요.')+'</p></div><button class="small" id="refill">캘린더로 다시 채우기</button></div><div class="sheet-head"><span>포함</span><span>과제</span><span>시간</span><span class="summary-label">업무 요약</span><span>편집</span></div>'+projects.map((p,i)=>{const r=reports[p.id];return '<section class="sheet-row '+(opened===i?'open':'')+'"><div class="sheet-summary"><input type="checkbox" data-include="'+p.id+'" aria-label="'+esc(p.name)+' 보고 포함" '+(r.included?'checked':'')+'><span class="sheet-project"><span class="dot" style="--pc:'+p.color+'"></span>'+esc(p.name)+'</span><input type="number" value="'+r.hours+'" min="0" step="0.25" data-hours="'+p.id+'" aria-label="'+esc(p.name)+' 투입 시간"><span class="sheet-preview">'+esc(includedBlocks(p.id).map(b=>b.text.split('\n')[0]).join(' / ')||'보고 내용 없음')+'</span><button class="small quiet" data-expand="'+i+'">'+(opened===i?'접기':'펼치기')+'</button></div>'+(opened===i?'<div class="sheet-expanded"><div>'+r.blocks.map(b=>blockHTML(b,p.id,true)).join('')+'<button class="add-text" data-free="'+p.id+'">+ 직접 입력</button>'+planHTML(p)+'</div><aside><strong>보고용으로 자유롭게 편집</strong><p>체크를 끄면 해당 블록만 제출 내용에서 빠집니다.</p><p>문구를 고쳐도 캘린더 일정과 메모는 바뀌지 않습니다.</p><p>시간은 캘린더의 날짜별 과제 시간에서 가져온 값입니다.</p></aside></div>':'')+'</section>';}).join('');w.appendChild(sheet);sheet.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{opened=opened===Number(b.dataset.expand)?-1:Number(b.dataset.expand);render();});sheet.querySelectorAll('[data-include]').forEach(c=>c.onchange=()=>{reports[c.dataset.include].included=c.checked;updateFoot();});$('#refill').onclick=showReplace;wireReport(w);}
function showReplace(){const box=$('#preview');$('#previewTitle').textContent='캘린더로 다시 채울까요?';$('#previewText').textContent='현재 보고용으로 편집한 내용이 캘린더의 원본 내용으로 교체됩니다.\n기존 회사 보고나 DB 기록은 이 시안에서 변경하지 않습니다.';box.querySelector('footer').innerHTML='<button id="confirmReplace" class="primary">초안 교체</button> <button id="cancelReplace">취소</button>';box.hidden=false;$('#confirmReplace').onclick=()=>{Object.values(reports).forEach(r=>r.blocks=[]);sources.forEach(s=>insert(s.id,false));box.hidden=true;render();notify('캘린더 원본으로 초안을 다시 만들었습니다.');};$('#cancelReplace').onclick=()=>box.hidden=true;}
function updateFoot(){const ps=projects.filter(p=>reports[p.id].included&&includedBlocks(p.id).some(b=>b.text.trim()));const n=ps.reduce((n,p)=>n+includedBlocks(p.id).length,0),hours=ps.reduce((n,p)=>n+(Number(reports[p.id].hours)||0),0);$('#footState').innerHTML='<strong>'+ps.length+'개 과제, '+n+'개 블록, '+Number(hours.toFixed(2))+'시간</strong><span class="foot-detail">　캘린더 원본은 그대로 유지</span>';}
function preview(){const ps=projects.filter(p=>reports[p.id].included&&includedBlocks(p.id).some(b=>b.text.trim()));if(!ps.length){notify('먼저 캘린더 내용을 추가하거나 업무를 직접 입력하세요.');return;}$('#previewTitle').textContent='회사에 보낼 내용';$('#previewText').textContent=date+(kind==='weekly'?' 주간보고':' 일간보고')+'\n\n'+ps.map(p=>'['+p.name+'] : '+reports[p.id].hours+'시간\n'+includedBlocks(p.id).map(b=>b.text).filter(t=>t.trim()).join('\n\n')+(kind==='weekly'?'\n\n차주 계획\n'+(reports[p.id].plan||'(미입력)'):'')).join('\n\n')+'\n\n근태: '+$('#attendanceStatus').value;$('#preview footer').textContent='프로토타입입니다. 실제 전송하지 않습니다. 블록은 과제별 보고 텍스트로 합쳐집니다.';$('#preview').hidden=false;$('#closePreview').focus();}
$$('.variants button').forEach(b=>b.onclick=()=>setCase(b.dataset.case));$('#taskCount').onchange=e=>{count=Number(e.target.value);init();};$('#scenario').onchange=e=>{scenario=e.target.value;init();};$('#reset').onclick=()=>{init();notify('현재 시안을 초기화했습니다.');};$('#reportDate').onchange=e=>{if(e.target.value)setDate(e.target.value);};function moveDate(n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);setDate(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'));}$('#prevDate').onclick=()=>moveDate(-1);$('#nextDate').onclick=()=>moveDate(1);$('#reportKind').onchange=e=>{kind=e.target.value;init();};$('#closeEditor').onclick=$('#closeFoot').onclick=()=>$('#veil').classList.add('hidden');$('#review').onclick=preview;$('#closePreview').onclick=()=>$('#preview').hidden=true;$('.research').addEventListener('toggle',positionVeil);window.addEventListener('resize',positionVeil);document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#preview').hidden)$('#preview').hidden=true;else $('#veil').classList.add('hidden');}});init();
